import React, { useState, useEffect, useRef, useCallback } from 'react';
import EventList from './components/EventList';
import BookingModal from './components/BookingModal';
import CreateEventForm from './components/CreateEventForm';
import BookingList from './components/BookingList';
import { getAllEvents, bookEvent, cancelBooking, createEvent, getAllBookings, WS_URL } from './api/eventsApi';

function App() {
  const [events, setEvents]           = useState([]);
  const [bookings, setBookings]       = useState([]);
  const [selectedEvent, setSelectedEvent] = useState(null);
  const [loading, setLoading]         = useState(false);
  const [message, setMessage]         = useState(null);
  const [error, setError]             = useState(null);
  const [wsStatus, setWsStatus]       = useState('connecting'); // connecting | open | closed
  const wsRef = useRef(null);

  const showMessage = (msg, isError = false) => {
    if (isError) { setError(msg); setMessage(null); }
    else { setMessage(msg); setError(null); }
    setTimeout(() => { setMessage(null); setError(null); }, 5000);
  };

  // ── Data fetching ────────────────────────────────────────────────────────

  const fetchAll = useCallback(async () => {
    try {
      const [eventsRes, bookingsRes] = await Promise.all([getAllEvents(), getAllBookings()]);
      setEvents(eventsRes.data);
      const enriched = bookingsRes.data.map((b) => ({
        ...b,
        eventName: eventsRes.data.find((e) => e.id === b.event_id)?.name || `Event #${b.event_id}`,
      }));
      setBookings(enriched);
    } catch (err) {
      showMessage(`Failed to load data: ${err.message}`, true);
    }
  }, []);

  // ── WebSocket setup ──────────────────────────────────────────────────────

  const connectWebSocket = useCallback(() => {
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) return;

    const ws = new WebSocket(WS_URL);
    wsRef.current = ws;

    ws.onopen = () => {
      setWsStatus('open');
    };

    ws.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data);
        if (data.type === 'seat_update') {
          // Instantly update the affected event's seat count — no HTTP round-trip needed
          setEvents((prev) =>
            prev.map((e) =>
              e.id === data.event_id
                ? { ...e, available_seats: data.available_seats }
                : e
            )
          );
        }
      } catch (_) {}
    };

    ws.onclose = () => {
      setWsStatus('closed');
      // Auto-reconnect after 3 seconds
      setTimeout(() => {
        setWsStatus('connecting');
        connectWebSocket();
      }, 3000);
    };

    ws.onerror = () => {
      ws.close();
    };
  }, []);

  // ── On mount ─────────────────────────────────────────────────────────────

  useEffect(() => {
    const init = async () => {
      setLoading(true);
      await fetchAll();
      setLoading(false);
    };
    init();
    connectWebSocket();

    return () => {
      if (wsRef.current) wsRef.current.close();
    };
  }, [fetchAll, connectWebSocket]);

  // ── Handlers ─────────────────────────────────────────────────────────────

  const handleBook = (event) => setSelectedEvent(event);

  const handleConfirmBooking = async (eventId, userName) => {
    setSelectedEvent(null);
    try {
      await bookEvent(eventId, userName);
      // WebSocket will update seat count; fetch bookings list to show new entry
      const bookingsRes = await getAllBookings();
      setBookings(
        bookingsRes.data.map((b) => ({
          ...b,
          eventName: events.find((e) => e.id === b.event_id)?.name || `Event #${b.event_id}`,
        }))
      );
      showMessage(`✅ Booking confirmed!`);
    } catch (err) {
      showMessage(`❌ Booking failed: ${err.message}`, true);
    }
  };

  const handleCancelBooking = async (bookingId) => {
    if (!window.confirm('Are you sure you want to cancel this booking?')) return;
    try {
      await cancelBooking(bookingId);
      // WebSocket will update seat count; refresh bookings list
      const bookingsRes = await getAllBookings();
      setBookings(
        bookingsRes.data.map((b) => ({
          ...b,
          eventName: events.find((e) => e.id === b.event_id)?.name || `Event #${b.event_id}`,
        }))
      );
      showMessage(`✅ Booking ${bookingId} cancelled. Seat restored.`);
    } catch (err) {
      showMessage(`❌ Cancel failed: ${err.message}`, true);
    }
  };

  const handleCreateEvent = async (eventData) => {
    try {
      await createEvent(eventData);
      showMessage(`✅ Event "${eventData.name}" created successfully!`);
      await fetchAll();
    } catch (err) {
      showMessage(`❌ Failed to create event: ${err.message}`, true);
    }
  };

  // ── Render ───────────────────────────────────────────────────────────────

  const wsIndicator = {
    open:       { color: '#28a745', label: '● Live' },
    connecting: { color: '#ffc107', label: '● Connecting...' },
    closed:     { color: '#dc3545', label: '● Disconnected' },
  }[wsStatus];

  return (
    <div style={{ fontFamily: 'Arial, sans-serif', maxWidth: '1100px', margin: '0 auto', padding: '20px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '2px solid #333', paddingBottom: '10px' }}>
        <h1 style={{ margin: 0 }}>🎟️ Event Booking System</h1>
        <span style={{ fontSize: '13px', color: wsIndicator.color, fontWeight: 'bold' }}>
          {wsIndicator.label}
        </span>
      </div>

      {message && (
        <div style={{ background: '#d4edda', border: '1px solid #28a745', padding: '12px', borderRadius: '4px', marginTop: '12px' }}>
          {message}
        </div>
      )}
      {error && (
        <div style={{ background: '#f8d7da', border: '1px solid #dc3545', padding: '12px', borderRadius: '4px', marginTop: '12px' }}>
          {error}
        </div>
      )}

      <EventList
        events={events}
        onBook={handleBook}
        onRefresh={fetchAll}
        loading={loading}
      />

      <BookingList bookings={bookings} onCancel={handleCancelBooking} />

      <CreateEventForm onCreateEvent={handleCreateEvent} />

      {selectedEvent && (
        <BookingModal
          event={selectedEvent}
          onConfirm={handleConfirmBooking}
          onClose={() => setSelectedEvent(null)}
        />
      )}
    </div>
  );
}

export default App;
